<?php
require __DIR__.'/../includes/bootstrap.php';require_admin($conn);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post_string('name',80);$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',$name),'-'));if($name){try{$st=$conn->prepare("INSERT INTO categories(name,slug) VALUES(?,?)");$st->bind_param('ss',$name,$slug);$st->execute();flash('success','Category added.');redirect('admin/categories.php');}catch(Throwable $e){$error='Could not add category. It may already exist.';}}}
$cats=$conn->query("SELECT c.id,c.name,c.slug,COUNT(b.id) books FROM categories c LEFT JOIN books b ON b.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetch_all(MYSQLI_ASSOC);$pageTitle='Categories';require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><p class="eyebrow">ADMINISTRATION</p><h1>Book <em>categories.</em></h1></div></section><section class="container section"><form method="post" class="admin-form compact"><?=csrf_field()?><h2>Add category</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="inline-form"><input name="name" placeholder="e.g. Fiction" maxlength="80" required><button class="btn btn-dark">Add category</button></div></form><div class="table-wrap mt-40"><table><thead><tr><th>Category</th><th>Slug</th><th>Books</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=$c['books']?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
